;(() => {
  const W = 1632, H = 918, F = (H / 2) / Math.tan((35 * Math.PI) / 180), EYE = 1.7;
  const cv = document.createElement("canvas");
  cv.width = W; cv.height = H;
  const c2 = cv.getContext("2d", { willReadFrequently: true });
  const luma = () => {
    const el = window.brDraw(W, H);
    c2.drawImage(el, 0, 0, W, H);
    const d = c2.getImageData(0, 0, W, H).data, out = new Float32Array(W * H);
    for (let i = 0, j = 0; i < out.length; i++, j += 4) out[i] = 0.299 * d[j] + 0.587 * d[j + 1] + 0.114 * d[j + 2];
    return out;
  };
  const BANDS = [[4, 6], [7, 10], [12, 18], [20, 30], [35, 45], [50, 70], [75, 95]];
  const rows = ([a, b]) => [Math.round(H / 2 + (F * EYE) / b), Math.round(H / 2 + (F * EYE) / a)];
  // views: { name: [x, z, headingDeg, x0, x1] } (columns x0..x1 as fractions of the width)
  window.brLab = async (views, variants, opts = {}) => {
    const ex = window.explorer, steps = opts.steps ?? 6, step = opts.step ?? 0.08;
    const out = {}, shots = [];
    for (const [vn, [x, z, hd, x0 = 0.2, x1 = 0.8]] of Object.entries(views)) {
      const dx = Math.sin((hd * Math.PI) / 180), dz = -Math.cos((hd * Math.PI) / 180);
      const c0 = Math.round(x0 * W), c1 = Math.round(x1 * W);
      out[vn] = {};
      for (const [name, reach, grow, taps = 16, lite = 0] of variants) {
        window.brGroundReach(reach, grow);
        window.brGroundTaps(taps);
        await ex.setGroundLite(!!lite);
        const frames = [];
        for (let k = 0; k < steps; k++) {
          const px = x + dx * step * k, pz = z + dz * step * k, y = ex.groundAt(px, pz) + EYE;
          await ex.view([px, y, pz], [px + dx * 100, y, pz + dz * 100], { near: 0.1, fov: 70 });
          frames.push(luma());
          if (k === 0) {
            const shot = document.createElement("canvas");
            shot.width = 816; shot.height = 150;
            shot.getContext("2d").drawImage(cv, W / 2 - 408, H / 2 - 6, 816, 150, 0, 0, 816, 150);
            shots.push([`${vn} ${name}`, shot]);
          }
        }
        const res = {};
        for (const band of BANDS) {
          const [r0, r1] = rows(band);
          let sharp = 0, n = 0, flick = 0, m = 0;
          for (let r = r0; r <= r1; r++)
            for (let c = c0; c < c1; c++) {
              const i = r * W + c;
              sharp += Math.abs(frames[0][i + 1] - frames[0][i]); n++;
              for (let k = 1; k < steps; k++) { flick += Math.abs(frames[k][i] - frames[k - 1][i]); m++; }
            }
          res[`${band[0]}-${band[1]}`] = [+(sharp / n).toFixed(2), +(flick / m).toFixed(2)];
        }
        out[vn][name] = res;
      }
    }
    let host = document.getElementById("lab-shots");
    if (!host) {
      host = document.createElement("div");
      host.id = "lab-shots";
      host.style.cssText = "position:fixed;inset:0;z-index:99999;background:#111;overflow:auto;font:12px monospace;color:#fff";
      document.body.appendChild(host);
    }
    host.innerHTML = "";
    for (const [label, shot] of shots) {
      const p = document.createElement("div");
      p.textContent = label;
      host.appendChild(p);
      shot.style.cssText = "display:block;width:816px;height:150px";
      host.appendChild(shot);
    }
    window.brLabShots = shots;
    return out;
  };
})();
